#include "pair-multicast-v2.h"
#include "../pair-jetty/pair-jetty-manager.h"
#include "ns3/core-module.h"
#include "ns3/network-module.h"
#include <filesystem>
#include <fstream>
using namespace ns3;
struct Stress {
 static constexpr uint32_t N=6;uint32_t bytes=1048576,delayNs=200000;std::string out;
 pairv2::Manager manager;std::vector<Ptr<Node>> nodes;std::unique_ptr<PairJettyManager> jetties;
 struct Child{uint32_t group,source,target,jetty,admitted{},covered{};bool done{};std::map<uint32_t,uint32_t> offsets;std::set<uint32_t> received;std::vector<uint8_t> data;};
 std::map<uint32_t,Child> children;std::map<uint32_t,std::vector<uint8_t>> payload;std::map<std::pair<uint32_t,uint32_t>,uint64_t> peakTa,wireBytes,envs,nativeWrites;std::ofstream events;
 uint32_t Tpn(uint32_t a,uint32_t b){return a*N+b+1;}Ptr<UbController> C(uint32_t n){return nodes[n]->GetObject<UbController>();}
 void Event(const std::string& event,uint32_t group,uint32_t task){events<<Simulator::Now().GetPicoSeconds()<<','<<event<<','<<group<<','<<task<<'\n';}
 void Init(){GlobalValue::Bind("UB_CC_ENABLED",BooleanValue(false));utils::UbUtils::Get();for(auto k:{"UB_TRACE_ENABLE","UB_PACKET_TRACE_ENABLE","UB_PORT_TRACE_ENABLE","UB_RECORD_PKT_TRACE"})GlobalValue::Bind(k,BooleanValue(false));
  Config::SetDefault("ns3::UbTransportChannel::DefaultMaxInflightPacketSize",UintegerValue(1000));Config::SetDefault("ns3::UbTransportChannel::DefaultMaxWqeSegNum",UintegerValue(1000));Config::SetDefault("ns3::UbJetty::UbJettyInflightMax",UintegerValue(512));
  for(uint32_t i=0;i<=N;++i){auto node=CreateObject<Node>();nodes.push_back(node);auto sw=CreateObject<UbSwitch>();node->AggregateObject(sw);sw->SetNodeType(i==N?UB_SWITCH:UB_DEVICE);if(i<N){auto c=CreateObject<UbController>();node->AggregateObject(c);c->CreateUbFunction();c->CreateUbTransaction();}for(uint32_t p=0;p<(i==N?N:1);++p){auto port=CreateObject<UbPort>();port->SetAddress(Mac48Address::Allocate());port->SetAttribute("UbDataRate",DataRateValue(DataRate("100Gbps")));node->AddDevice(port);}sw->Init();UbCongestionControl::Create(UB_SWITCH)->OnSwitchAttached(sw);}
  for(uint32_t i=0;i<N;++i){auto link=CreateObject<UbLink>();link->SetAttribute("Delay",TimeValue(NanoSeconds(20)));DynamicCast<UbPort>(nodes[i]->GetDevice(0))->Attach(link);DynamicCast<UbPort>(nodes[N]->GetDevice(i))->Attach(link);}
  for(uint32_t i=0;i<=N;++i)for(uint32_t d=0;d<N;++d)if(i!=d){auto& t=nodes[i]->GetObject<UbSwitch>()->GetRoutingProcess()->GetRoutingTable();uint16_t port=i==N?d:0;t.AddShortestRoute(NodeIdToIp(d).Get(),{port});t.AddShortestRoute(NodeIdToIp(d,0).Get(),{port});}
  std::vector<uint32_t> ports;for(uint32_t i=0;i<N;++i)ports.push_back(i);auto fabric=nodes[N]->GetObject<UbSwitch>();fabric->EnableNetworkReplication(ports);
  struct Spec{uint32_t id,source;std::vector<uint32_t> targets;};std::vector<Spec> specs={{1,0,{1,2}},{2,0,{2,3}},{3,1,{0,2}},{4,2,{0,1}},{5,4,{3,5}}};
  std::set<std::pair<uint32_t,uint32_t>> edges;for(auto&g:specs)for(auto dst:g.targets)edges.insert(std::minmax(g.source,dst));
  for(auto[a,b]:edges){Connection c;c.ownerNodeId=a;c.node1=a;c.node2=b;c.port1=c.port2=0;c.tpn1=Tpn(a,b);c.tpn2=Tpn(b,a);c.priority=7;c.metrics=0;C(a)->GetTpConnManager()->AddUnilateralConnection(c,a);C(b)->GetTpConnManager()->AddUnilateralConnection(c,b);for(auto[s,d]:{std::pair{a,b},std::pair{b,a}}){C(s)->GetTransportChannelManager()->CreateTp(s,d,0,0,7,Tpn(s,d),Tpn(d,s),UbCongestionControl::Create(UB_DEVICE));auto tp=C(s)->GetTransportChannelManager()->GetTp(Tpn(s,d));tp->TraceConnectWithoutContext("WqeSegmentSendsNotify",Callback<void,uint32_t,uint32_t,uint32_t>([this,s,d](uint32_t,uint32_t task,uint32_t ssn){auto&c=children.at(task);if(s==c.source){NS_ABORT_MSG_IF(c.admitted>=bytes||!c.offsets.emplace(ssn,c.admitted).second,"admission identity");c.admitted+=std::min(1024u,bytes-c.admitted);auto j=C(s)->GetUbFunction()->GetJetty(c.jetty);peakTa[{s,d}]=std::max(peakTa[{s,d}],uint64_t(j->GetTaSsnSndNxtForTest()-j->GetTaSsnSndUnaForTest()));}manager.Refresh(s,d);}));}}
  jetties=std::make_unique<PairJettyManager>([this](uint32_t r){return C(r);},N,1024,Callback<void,uint32_t,uint32_t>([this](uint32_t task,uint32_t jetty){auto&c=children.at(task);NS_ABORT_MSG_IF(c.jetty!=jetty||c.done||c.covered!=bytes,"early/duplicate WQE completion");c.done=true;Event("sender_complete",c.group,task);manager.Completed(task);}));
  for(auto&g:specs){auto&data=payload[g.id];data.resize(bytes);for(uint32_t i=0;i<bytes;++i)data[i]=(g.id*73+i*131+(i>>8)*17)%251;std::vector<pairv2::Manager::Member> members;for(auto dst:g.targets){uint32_t task=g.id*10+dst;auto tx=C(g.source)->GetTransportChannelManager()->GetTp(Tpn(g.source,dst));auto rx=C(dst)->GetTransportChannelManager()->GetTp(Tpn(dst,g.source));auto j=jetties->Get(g.source,dst,Tpn(g.source,dst));Child child{g.id,g.source,dst,j.id};child.data.resize(bytes);children.emplace(task,std::move(child));members.push_back({dst,task,tx,rx});}manager.Add(g.id,g.source,bytes,1024,DynamicCast<UbPort>(nodes[g.source]->GetDevice(0)),members);}
  manager.offset=[this](uint32_t task,uint32_t ssn){return children.at(task).offsets.at(ssn);};
  manager.submit=[this](uint32_t task){auto&c=children.at(task);auto w=C(c.source)->GetUbFunction()->CreateWqe(c.source,c.target,bytes,task,UbTransactionOpcode::WRITE);w->SetExplicitPayload(Create<Packet>(payload.at(c.group).data(),bytes));NS_ABORT_MSG_IF(C(c.source)->GetUbFunction()->SubmitWqe(w,c.jetty).status!=UbWqeSubmissionStatus::ACCEPTED,"native submit");Event("submit",c.group,task);manager.Refresh(c.source,c.target);};
  for(uint32_t s=0;s<N;++s){auto port=DynamicCast<UbPort>(nodes[s]->GetDevice(0));if(manager.HasSource(s)){std::vector<Ptr<UbTransportChannel>> channels;for(uint32_t d=0;d<N;++d)if(d!=s){auto tp=C(s)->GetTransportChannelManager()->GetTp(Tpn(s,d));if(tp)channels.push_back(tp);}manager.InstallSource(s,port,channels,fabric);port->SetReceiveHandler(Callback<void,Ptr<UbPort>,Ptr<Packet>>([this,s](Ptr<UbPort> p,Ptr<Packet>b){manager.Receive(s,p,b);}));}
   C(s)->GetUbTransaction()->SetTargetExecutor(UbTargetExecutor([this,s](Ptr<const UbWqeSegment> req,const UbTransactionRule&,UbTargetCompletion done){auto task=req->GetTaskId();auto&c=children.at(task);auto ssn=req->GetTaSsn();NS_ABORT_MSG_IF(s!=c.target||req->GetSrc()!=c.source||req->GetJettyNum()!=c.jetty||!c.received.insert(ssn).second,"target identity/duplicate");auto off=c.offsets.at(ssn),len=req->GetPayloadBytes();NS_ABORT_MSG_IF(len!=std::min(1024u,bytes-off),"target size");std::vector<uint8_t> b(len);req->GetExplicitPayload()->CopyData(b.data(),len);NS_ABORT_MSG_IF(!std::equal(b.begin(),b.end(),payload.at(c.group).begin()+off),"wire payload mismatch");std::copy(b.begin(),b.end(),c.data.begin()+off);auto finish=[this,task,len,done]{auto&c=children.at(task);done(UbWorkExecutionResult{});c.covered+=len;NS_ABORT_MSG_IF(c.covered>bytes,"overcoverage");if(c.covered==bytes)Event("receiver_ready",c.group,task);};if(c.target==2)Simulator::Schedule(NanoSeconds(delayNs),finish);else finish();}));
  }
  for(uint32_t node=0;node<=N;++node)for(uint32_t p=0;p<nodes[node]->GetNDevices();++p){auto port=DynamicCast<UbPort>(nodes[node]->GetDevice(p));port->TraceConnectWithoutContext("TraComEventNotify",Callback<void,Ptr<Packet>,Time>([this,node,p](Ptr<Packet>b,Time){wireBytes[{node,p}]+=b->GetSize();if(UbWriteV2::IsEnvelope(b)){++envs[{node,p}];return;}auto sw=nodes[node]->GetObject<UbSwitch>();if(sw->GetPacketTypeForTest(b)!=UB_URMA_DATA_PACKET)return;auto q=b->Copy();UbDatalinkPacketHeader dl;UbIpBasedNetworkHeader net;Ipv4Header ip;UdpHeader udp;UbTransportHeader tp;q->RemoveHeader(dl);q->RemoveHeader(net);q->RemoveHeader(ip);q->RemoveHeader(udp);q->RemoveHeader(tp);if(!UbTransportChannel::IsTransportResponseOpcode(tp.GetTPOpcode())){UbTransactionHeader ta;q->PeekHeader(ta);if(ta.GetUbTransactionOpcode()==uint8_t(UbTransactionOpcode::WRITE))++nativeWrites[{node,p}];}}));}
  manager.CheckCapacity(nodes);
 }
 void Run(){std::filesystem::create_directories(out);events.open(out+"/events.csv");events<<"time_ps,event,group,task\n";Init();Simulator::Schedule(NanoSeconds(100),[this]{manager.Start();});Simulator::Stop(MilliSeconds(10));Simulator::Run();manager.CheckDrained();jetties->CheckIdle();
  for(auto&[task,c]:children)NS_ABORT_MSG_IF(!c.done||c.admitted!=bytes||c.covered!=bytes||c.data!=payload.at(c.group),"final child bytes/state");
  std::ofstream gs(out+"/groups.csv");gs<<"group,source,admitted_ps,first_send_done_ps,complete_ps,envelopes,association_peak,association_limit\n";for(auto&[id,g]:manager.groups)gs<<id<<','<<g.source<<','<<g.admittedPs<<','<<g.releasedPs<<','<<manager.completeTimes.at(id)<<','<<g.codec->envelopes<<','<<g.codec->peakRecords<<','<<g.codec->capacity<<'\n';
  uint64_t peak=0;for(auto&[key,x]:peakTa)peak=std::max(peak,x);NS_ABORT_MSG_IF(bytes>512*1024&&delayNs>=200000&&peak<512,"Jetty window boundary not exercised");
  std::ofstream ps(out+"/ports.csv");ps<<"node,port,wire_bytes,envelopes,native_writes,consumed,returned,restored,pending\n";
  for(uint32_t node=0;node<=N;++node){auto sw=nodes[node]->GetObject<UbSwitch>();NS_ABORT_MSG_IF(sw->GetQueueManager()->GetSwitchBufferOccupancy().total_buffered_bytes,"switch queues not drained");for(uint32_t p=0;p<nodes[node]->GetNDevices();++p){auto port=DynamicCast<UbPort>(nodes[node]->GetDevice(p));auto fc=DynamicCast<UbCbfc>(port->GetFlowControl());auto peer=DynamicCast<UbPort>(nodes[node==N?p:N]->GetDevice(node==N?0:node));auto other=DynamicCast<UbCbfc>(peer->GetFlowControl());NS_ABORT_MSG_IF(port->GetUbQueue()->GetCurrentBytes()||fc->GetConsumedCells()!=other->GetReturnedCells()||fc->GetConsumedCells()!=fc->GetRestoredCells()+uint64_t(other->GetCrdToReturn(7)),"CBFC/queue conservation");ps<<node<<','<<p<<','<<wireBytes[{node,p}]<<','<<envs[{node,p}]<<','<<nativeWrites[{node,p}]<<','<<fc->GetConsumedCells()<<','<<fc->GetReturnedCells()<<','<<fc->GetRestoredCells()<<','<<fc->GetCrdToReturn(7)<<'\n';}if(node<N)for(uint32_t dst=0;dst<N;++dst)if(dst!=node){auto tp=C(node)->GetTransportChannelManager()->GetTp(Tpn(node,dst));NS_ABORT_MSG_IF(tp&&!tp->IsSafeForExplicitDestroy(),"TP not quiescent");}}
  NS_ABORT_MSG_IF(manager.groups.at(5).admittedPs!=manager.groups.at(1).admittedPs||manager.groups.at(2).admittedPs<manager.groups.at(1).releasedPs,"reservation concurrency/order");
  std::ofstream f(out+"/summary.json");f<<"{\"status\":\"PASS\",\"groups\":5,\"children\":"<<children.size()<<",\"pair_jetties\":"<<jetties->Size()<<",\"peak_ta_inflight\":"<<peak<<",\"bytes_per_child\":"<<bytes<<",\"delay_ns\":"<<delayNs<<"}\n";Simulator::Destroy();
 }
};
int main(int argc,char**argv){Time::SetResolution(Time::PS);Stress t;CommandLine c;c.AddValue("out","Private output",t.out);c.AddValue("bytes","Bounded bytes per child",t.bytes);c.AddValue("delayNs","Asymmetric test-only target delay",t.delayNs);c.Parse(argc,argv);NS_ABORT_MSG_IF(t.out.empty()||!t.bytes||t.bytes>1048576||t.bytes%1024,"stress bounds");t.Run();}
